"""Binary Tree Preorder Traversal — stack, pushing right before left.

Time: O(n)   Space: O(h)
"""
from typing import List

if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def preorderTraversal(self, root) -> List[int]:
        if not root:
            return []
        out, stack = [], [root]
        while stack:
            node = stack.pop()
            out.append(node.val)
            if node.right:
                stack.append(node.right)
            if node.left:
                stack.append(node.left)
        return out
